public with sharing class RecordSearchService {
    public class SearchException extends Exception {}

    public static List<SObject> search(String objectApiName, List<String> fields, Map<String, Object> filters, String orderByField, Integer maxRows) {
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200 inclusive');
        }

        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name is required');
        }

        Schema.SObjectType objType = resolveSObjectType(objectApiName);
        if (objType == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }

        Schema.DescribeSObjectResult objDesc = objType.getDescribe();
        if (!objDesc.isAccessible() || !objDesc.isQueryable()) {
            throw new SearchException('User cannot read object: ' + objectApiName);
        }

        if (fields == null || fields.isEmpty()) {
            throw new SearchException('Fields list is required');
        }

        Map<String, Schema.DescribeFieldResult> fieldDescribes = buildFieldMap(objDesc);

        Set<String> selectedFields = new Set<String>();
        selectedFields.add('Id');

        for (String f : fields) {
            if (String.isBlank(f)) {
                throw new SearchException('Field name cannot be blank');
            }
            Schema.DescribeFieldResult d = getFieldDescribe(fieldDescribes, f);
            if (d == null) {
                throw new SearchException('Field does not exist: ' + f);
            }
            if (!d.isAccessible()) {
                throw new SearchException('Field is not readable: ' + f);
            }
            selectedFields.add(d.getName());
        }

        if (filters != null && !filters.isEmpty()) {
            for (String filterKey : filters.keySet()) {
                if (String.isBlank(filterKey)) {
                    throw new SearchException('Filter key cannot be blank');
                }
                Schema.DescribeFieldResult d = getFieldDescribe(fieldDescribes, filterKey);
                if (d == null) {
                    throw new SearchException('Filter field does not exist: ' + filterKey);
                }
                if (!d.isAccessible()) {
                    throw new SearchException('Filter field is not readable: ' + filterKey);
                }
                if (!d.isFilterable()) {
                    throw new SearchException('Filter field is not filterable: ' + filterKey);
                }
            }
        }

        String orderApiName = null;
        if (String.isNotBlank(orderByField)) {
            Schema.DescribeFieldResult d = getFieldDescribe(fieldDescribes, orderByField);
            if (d == null) {
                throw new SearchException('Order field does not exist: ' + orderByField);
            }
            if (!d.isAccessible()) {
                throw new SearchException('Order field is not readable: ' + orderByField);
            }
            if (!d.isSortable()) {
                throw new SearchException('Order field is not sortable: ' + orderByField);
            }
            orderApiName = d.getName();
        }

        String soql = 'SELECT ' + String.join(new List<String>(selectedFields), ', ') + ' FROM ' + objDesc.getName();

        List<String> conditions = new List<String>();
        if (filters != null && !filters.isEmpty()) {
            for (String filterKey : filters.keySet()) {
                Schema.DescribeFieldResult d = getFieldDescribe(fieldDescribes, filterKey);
                String apiName = d.getName();
                Object val = filters.get(filterKey);
                conditions.add(apiName + ' = ' + formatValue(val));
            }
        }

        if (!conditions.isEmpty()) {
            soql += ' WHERE ' + String.join(conditions, ' AND ');
        }

        if (String.isNotBlank(orderApiName)) {
            soql += ' ORDER BY ' + orderApiName + ' ASC';
        }

        soql += ' LIMIT ' + maxRows;

        try {
            return Database.query(soql);
        } catch (Exception e) {
            throw new SearchException('Search execution failed: ' + e.getMessage());
        }
    }

    private static Schema.SObjectType resolveSObjectType(String apiName) {
        if (String.isBlank(apiName)) {
            return null;
        }
        Map<String, Schema.SObjectType> globalMap = Schema.getGlobalDescribe();
        Schema.SObjectType result = globalMap.get(apiName);
        if (result != null) {
            return result;
        }
        String lowerName = apiName.toLowerCase();
        for (String key : globalMap.keySet()) {
            if (key != null && key.toLowerCase() == lowerName) {
                return globalMap.get(key);
            }
        }
        return null;
    }

    private static Map<String, Schema.DescribeFieldResult> buildFieldMap(Schema.DescribeSObjectResult objDesc) {
        Map<String, Schema.DescribeFieldResult> result = new Map<String, Schema.DescribeFieldResult>();
        for (Schema.SObjectField token : objDesc.fields.getMap().values()) {
            Schema.DescribeFieldResult d = token.getDescribe();
            if (d != null) {
                result.put(d.getName().toLowerCase(), d);
            }
        }
        return result;
    }

    private static Schema.DescribeFieldResult getFieldDescribe(Map<String, Schema.DescribeFieldResult> describes, String fieldName) {
        if (describes == null || String.isBlank(fieldName)) {
            return null;
        }
        return describes.get(fieldName.toLowerCase());
    }

    private static String formatValue(Object value) {
        if (value == null) {
            return 'null';
        }
        if (value instanceof String || value instanceof Id) {
            return '''' + String.escapeSingleQuotes(String.valueOf(value)) + '''';
        }
        if (value instanceof Boolean) {
            return String.valueOf(value).toLowerCase();
        }
        if (value instanceof Integer || value instanceof Long || value instanceof Double || value instanceof Decimal) {
            return String.valueOf(value);
        }
        if (value instanceof Date) {
            Date d = (Date) value;
            return d.year() + '-' + String.valueOf(d.month()).leftPad(2, '0') + '-' + String.valueOf(d.day()).leftPad(2, '0');
        }
        if (value instanceof DateTime) {
            DateTime dt = (DateTime) value;
            String y = String.valueOf(dt.year());
            String m = String.valueOf(dt.month()).leftPad(2, '0');
            String d = String.valueOf(dt.day()).leftPad(2, '0');
            String h = String.valueOf(dt.hour()).leftPad(2, '0');
            String min = String.valueOf(dt.minute()).leftPad(2, '0');
            String s = String.valueOf(dt.second()).leftPad(2, '0');
            return y + '-' + m + '-' + d + ' ' + h + ':' + min + ':' + s;
        }
        return '''' + String.escapeSingleQuotes(String.valueOf(value)) + '''';
    }
}
