public class PicklistService {

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option() {}

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {}

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        try {
            if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
                throw new PicklistServiceException('Object or field API name is null or blank.');
            }

            Schema.SObjectType objType = Schema.getGlobalDescribe().get(objectApiName);
            if (objType == null) {
                for (Schema.SObjectType s : Schema.getGlobalDescribe().values()) {
                    Schema.DescribeSObjectResult d = s.getDescribe();
                    if (d.getName() != null && d.getName().equalsIgnoreCase(objectApiName)) {
                        objType = s;
                        break;
                    }
                }
            }

            if (objType == null) {
                throw new PicklistServiceException('Object does not exist: ' + objectApiName);
            }

            Schema.DescribeSObjectResult objDesc = objType.getDescribe();
            Schema.SObjectField fieldToken = null;

            for (Schema.SObjectField f : objDesc.fields.getMap().values()) {
                Schema.DescribeFieldResult fDesc = f.getDescribe();
                if (fDesc.getName() != null && fDesc.getName().equalsIgnoreCase(fieldApiName)) {
                    fieldToken = f;
                    break;
                }
            }

            if (fieldToken == null) {
                throw new PicklistServiceException('Field does not exist on object: ' + fieldApiName);
            }

            Schema.DescribeFieldResult fieldDesc = fieldToken.getDescribe();
            Schema.DisplayType dt = fieldDesc.getType();
            if (dt != Schema.DisplayType.PICKLIST && dt != Schema.DisplayType.MULTIPICKLIST) {
                throw new PicklistServiceException('Field is not a picklist or multi-select picklist.');
            }

            List<Option> result = new List<Option>();
            for (Schema.PicklistEntry entry : fieldDesc.getPicklistValues()) {
                if (entry.isActive()) {
                    result.add(new Option(entry.getValue(), entry.getLabel(), entry.isDefaultValue()));
                }
            }

            return result;
        } catch (PicklistServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new PicklistServiceException('Unexpected error: ' + e.getMessage());
        }
    }
}
