public class AccountOnboardingService {
    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        List<Account> accounts = new List<Account>();
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return accounts;
        }

        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<SObjectType>{
                Account.sObjectType,
                Contact.sObjectType
            }
        );

        List<String> accountNames = new List<String>();

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            Account acc = new Account(Name = accountName);
            accounts.add(acc);
            accountNames.add(accountName);
            uow.registerNew(acc);

            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames != null) {
                for (String lastName : lastNames) {
                    Contact con = new Contact(LastName = lastName);
                    con.Account = acc;
                    uow.registerNew(con);
                }
            }
        }

        uow.commitWork();

        // Ensure returned accounts carry their Ids (retrieve via query in case the UOW references need refresh)
        if (!accounts.isEmpty() && !accountNames.isEmpty()) {
            Map<String, Account> byName = new Map<String, Account>();
            for (Account a : [
                SELECT Id, Name
                FROM Account
                WHERE Name IN :accountNames
            ]) {
                byName.put(a.Name, a);
            }
            List<Account> ordered = new List<Account>();
            for (String name : accountNames) {
                if (byName.containsKey(name)) {
                    ordered.add(byName.get(name));
                }
            }
            accounts = ordered;
        }

        return accounts;
    }
}
