public with sharing class ErpCustomerSync {
    // Deviation: direct callouts from triggers are not allowed by the platform.
    // We use Queueable (Database.AllowsCallouts) with one request per account.
    // Batches are chunked to 100 accounts per Queueable to stay under the
    // 100-callout limit for marketplace batches up to 200.

    public static void syncAccount(Account acc) {
        syncAccounts(new List<Account>{ acc });
    }

    public static void syncAccounts(List<Account> accounts) {
        if (accounts == null || accounts.isEmpty()) {
            return;
        }
        List<Id> ids = new List<Id>();
        for (Account acc : accounts) {
            if (acc.Id != null) {
                ids.add(acc.Id);
            }
        }

        // One Queueable per 100 accounts = at most 2 jobs for a batch of 200.
        for (Integer i = 0; i < ids.size(); i += 100) {
            List<Id> chunk = new List<Id>();
            for (Integer j = i; j < Math.min(i + 100, ids.size()); j++) {
                chunk.add(ids[j]);
            }
            System.enqueueJob(new ErpCustomerSyncQueueable(chunk));
        }
    }

    public with sharing class ErpCustomerSyncQueueable implements Queueable, Database.AllowsCallouts {
        private List<Id> accountIds;

        public ErpCustomerSyncQueueable(List<Id> accountIds) {
            this.accountIds = accountIds;
        }

        public void execute(QueueableContext context) {
            List<Account> accounts = [
                SELECT Id, Name, BillingCountry
                FROM Account
                WHERE Id IN :accountIds
            ];

            for (Account acc : accounts) {
                Map<String, Object> customer = new Map<String, Object>{
                    'salesforceId' => acc.Id,
                    'name' => acc.Name,
                    'country' => acc.BillingCountry
                };

                String body = JSON.serialize(new List<Object>{ customer });

                HttpRequest req = new HttpRequest();
                req.setEndpoint('callout:ERP/api/customers');
                req.setMethod('POST');
                req.setHeader('Content-Type', 'application/json');
                req.setBody(body);
                req.setTimeout(120000);

                Http http = new Http();
                HttpResponse res = http.send(req);
            }
        }
    }
}
