public class GiftImportService {
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            npsp__DataImport__c rec = new npsp__DataImport__c();
            rec.npsp__Contact1_Firstname__c = gift.firstName;
            rec.npsp__Contact1_Lastname__c = gift.lastName;
            rec.npsp__Contact1_Personal_Email__c = gift.email;
            rec.npsp__Donation_Amount__c = gift.amount;
            rec.npsp__Donation_Date__c = gift.giftDate;
            rec.npsp__Donation_Donor__c = 'Contact1';
            staged.add(rec);
        }

        if (!staged.isEmpty()) {
            insert staged;
        }

        List<Id> recordIds = new List<Id>();
        for (npsp__DataImport__c rec : staged) {
            recordIds.add(rec.Id);
        }

        String systemError = null;
        try {
            npsp.BatchDataImport bdi = new npsp.BatchDataImport();
            bdi.processBatchDataImport(staged);
        } catch (Exception e) {
            systemError = e.getMessage();
        }

        Map<Id, npsp__DataImport__c> processed = new Map<Id, npsp__DataImport__c>(
            [SELECT Id, npsp__Status__c, npsp__Contact1Imported__c,
                    npsp__DonationImported__c, npsp__FailureInformation__c
             FROM npsp__DataImport__c
             WHERE Id IN :recordIds]
        );

        List<ImportResult> results = new List<ImportResult>();
        for (Integer i = 0; i < gifts.size(); i++) {
            Id recId = recordIds[i];
            ImportResult res = new ImportResult();
            npsp__DataImport__c proc = processed.get(recId);

            if (proc == null) {
                res.success = false;
                res.errorMessage = 'Data Import record not found after processing.';
            } else {
                Boolean imported = (proc.npsp__Status__c == 'Imported');
                res.success = imported;
                if (imported) {
                    res.contactId = proc.npsp__Contact1Imported__c;
                    res.opportunityId = proc.npsp__DonationImported__c;
                } else {
                    res.contactId = null;
                    res.opportunityId = null;
                    res.errorMessage = proc.npsp__FailureInformation__c;
                    if (String.isBlank(res.errorMessage)) {
                        res.errorMessage = proc.npsp__Status__c;
                    }
                    if (String.isBlank(res.errorMessage) && systemError != null) {
                        res.errorMessage = systemError;
                    }
                }
            }
            results.add(res);
        }

        return results;
    }
}
