public with sharing class HouseholdService {
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('Members list cannot be null or empty.');
        }

        // Ensure members are new and have no existing Account linkage
        for (Contact c : members) {
            c.AccountId = null;
        }

        // Insert members first so the primary contact has an Id for the household
        insert members;

        // Resolve Household Account record type without hard-coding an Id
        RecordTypeInfo hhRTInfo = Schema.SObjectType.Account.getRecordTypeInfosByDeveloperName()
            .get('HH_Account');
        if (hhRTInfo == null) {
            throw new IllegalStateException('Household Account record type (HH_Account) not found.');
        }
        Id hhRecordTypeId = hhRTInfo.getRecordTypeId();

        // Create the household account; NPSP names it because the primary contact is set
        Account household = new Account(
            RecordTypeId = hhRecordTypeId,
            npe01__One2OneContact__c = members[0].Id
        );

        insert household;

        // Link all members to the single new household
        for (Contact c : members) {
            c.AccountId = household.Id;
        }
        update members;

        // Remove any empty household accounts NPSP may have auto-created
        // when members were inserted without an AccountId
        List<Account> extraHouseholds = [
            SELECT Id FROM Account
            WHERE RecordType.DeveloperName = 'HH_Account'
            AND Id != :household.Id
            AND Id NOT IN (
                SELECT AccountId FROM Contact WHERE AccountId != null
            )
        ];

        if (!extraHouseholds.isEmpty()) {
            delete extraHouseholds;
        }

        return household.Id;
    }
}
