public class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();

        for (SoftCreditRequest req : requests) {
            if (req != null) {
                if (req.opportunityId != null) {
                    oppIds.add(req.opportunityId);
                }
                if (req.contactId != null) {
                    contactIds.add(req.contactId);
                }
            }
        }

        // Query 1: Opportunities for validation
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [
                SELECT Id, npsp__Primary_Contact__c, Amount
                FROM Opportunity
                WHERE Id IN :oppIds
            ]
        );

        Set<String> seenKeys = new Set<String>();

        for (SoftCreditRequest req : requests) {
            if (req == null) {
                throw new SoftCreditException('Request is null');
            }
            if (req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException('Opportunity or Contact is missing');
            }
            if (String.isBlank(req.role)) {
                throw new SoftCreditException('Role is missing');
            }

            String key = req.opportunityId + '-' + req.contactId;
            if (seenKeys.contains(key)) {
                throw new SoftCreditException('Duplicate opportunity/contact pair');
            }
            seenKeys.add(key);

            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found');
            }

            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException('Contact is the primary contact');
            }

            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Amount must be positive');
            }

            if (opp.Amount == null || req.amount > opp.Amount) {
                throw new SoftCreditException('Amount exceeds opportunity amount');
            }
        }

        // Query 2: Existing OpportunityContactRoles
        List<OpportunityContactRole> existingOCRs = [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds
              AND ContactId IN :contactIds
        ];

        Map<String, List<OpportunityContactRole>> ocrByKey = new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : existingOCRs) {
            String k = ocr.OpportunityId + '-' + ocr.ContactId;
            if (!ocrByKey.containsKey(k)) {
                ocrByKey.put(k, new List<OpportunityContactRole>());
            }
            ocrByKey.get(k).add(ocr);
        }

        // Query 3: Existing Partial Soft Credits
        List<npsp__Partial_Soft_Credit__c> existingPSCs = [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c,
                   npsp__Amount__c, npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds
              AND npsp__Contact__c IN :contactIds
        ];

        Map<String, List<npsp__Partial_Soft_Credit__c>> pscByKey = new Map<String, List<npsp__Partial_Soft_Credit__c>>();
        for (npsp__Partial_Soft_Credit__c psc : existingPSCs) {
            String k = psc.npsp__Opportunity__c + '-' + psc.npsp__Contact__c;
            if (!pscByKey.containsKey(k)) {
                pscByKey.put(k, new List<npsp__Partial_Soft_Credit__c>());
            }
            pscByKey.get(k).add(psc);
        }

        // Build deduplicated request map
        Map<String, SoftCreditRequest> uniqueRequests = new Map<String, SoftCreditRequest>();
        for (SoftCreditRequest req : requests) {
            if (req != null) {
                String k = req.opportunityId + '-' + req.contactId;
                uniqueRequests.put(k, req);
            }
        }

        List<OpportunityContactRole> ocrToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrToUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrToDelete = new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> ocrLink = new Map<String, OpportunityContactRole>();

        for (String k : uniqueRequests.keySet()) {
            SoftCreditRequest req = uniqueRequests.get(k);
            List<OpportunityContactRole> listOCR = ocrByKey.containsKey(k) ? ocrByKey.get(k) : new List<OpportunityContactRole>();

            OpportunityContactRole target = null;
            List<OpportunityContactRole> extras = new List<OpportunityContactRole>();

            if (listOCR.isEmpty()) {
                target = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                ocrToInsert.add(target);
            } else {
                Integer matchIdx = -1;
                for (Integer i = 0; i < listOCR.size(); i++) {
                    if (listOCR[i].Role == req.role) {
                        matchIdx = i;
                        break;
                    }
                }

                if (matchIdx >= 0) {
                    target = listOCR[matchIdx];
                    for (Integer i = 0; i < listOCR.size(); i++) {
                        if (i != matchIdx) {
                            extras.add(listOCR[i]);
                        }
                    }
                } else {
                    target = listOCR[0];
                    for (Integer i = 1; i < listOCR.size(); i++) {
                        extras.add(listOCR[i]);
                    }
                }

                if (target.Role != req.role) {
                    target.Role = req.role;
                    ocrToUpdate.add(target);
                }

                ocrToDelete.addAll(extras);
            }

            ocrLink.put(k, target);
        }

        // DML 1
        if (!ocrToInsert.isEmpty()) {
            insert ocrToInsert;
        }

        // DML 2
        if (!ocrToUpdate.isEmpty()) {
            update ocrToUpdate;
        }

        // DML 3
        if (!ocrToDelete.isEmpty()) {
            delete ocrToDelete;
        }

        List<npsp__Partial_Soft_Credit__c> pscUpsert = new List<npsp__Partial_Soft_Credit__c>();

        for (String k : uniqueRequests.keySet()) {
            SoftCreditRequest req = uniqueRequests.get(k);
            OpportunityContactRole targetOCR = ocrLink.get(k);

            List<npsp__Partial_Soft_Credit__c> listPSC = pscByKey.containsKey(k) ? pscByKey.get(k) : new List<npsp__Partial_Soft_Credit__c>();

            npsp__Partial_Soft_Credit__c psc;
            if (!listPSC.isEmpty()) {
                psc = listPSC[0];
                psc.npsp__Opportunity__c = req.opportunityId;
                psc.npsp__Contact__c = req.contactId;
                psc.npsp__Amount__c = req.amount;
                psc.npsp__Role_Name__c = req.role;
                psc.npsp__Contact_Role_ID__c = targetOCR.Id;
            } else {
                psc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role,
                    npsp__Contact_Role_ID__c = targetOCR.Id
                );
            }

            pscUpsert.add(psc);
        }

        // DML 4
        if (!pscUpsert.isEmpty()) {
            upsert pscUpsert;
        }
    }
}
