public class FamilyService {
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> allIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId != null) {
                allIds.add(childId);
            }
            if (parentId != null) {
                allIds.add(parentId);
            }
        }
        if (allIds.isEmpty()) {
            return;
        }

        // 1. Gather gender for all involved contacts
        Map<Id, String> genderById = new Map<Id, String>();
        for (Contact c : [
            SELECT Id, Gender FROM Contact WHERE Id IN :allIds
        ]) {
            genderById.put(c.Id, c.Gender);
        }

        // 2. Find any existing relationship in either direction
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT Id, npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allIds
               OR npe4__RelatedContact__c IN :allIds
        ]) {
            existingPairs.add(rel.npe4__Contact__c + ':' + rel.npe4__RelatedContact__c);
            existingPairs.add(rel.npe4__RelatedContact__c + ':' + rel.npe4__Contact__c);
        }

        // 3. Active relationship lookups needed for the types
        Map<String, Id> lookupByName = new Map<String, Id>();
        for (npe4__Relationship_Lookup__c l : [
            SELECT Id, Name
            FROM npe4__Relationship_Lookup__c
            WHERE Name IN ('Parent', 'Son', 'Daughter', 'Child')
              AND npe4__Active__c = true
        ]) {
            lookupByName.put(l.Name, l.Id);
        }

        Id parentLookupId = lookupByName.get('Parent');
        if (parentLookupId == null) {
            return;
        }

        Id sonLookupId    = lookupByName.get('Son');
        Id daughterLookupId = lookupByName.get('Daughter');
        Id childLookupId  = lookupByName.get('Child');

        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            if (parentId == null || childId == null || childId.equals(parentId)) {
                continue;
            }

            String key    = childId + ':' + parentId;
            String revKey = parentId + ':' + childId;
            if (existingPairs.contains(key) || existingPairs.contains(revKey)) {
                continue;
            }

            String gender = genderById.get(childId);
            Id reciprocalLookupId;
            if ('Male'.equalsIgnoreCase(gender)) {
                reciprocalLookupId = sonLookupId;
            } else if ('Female'.equalsIgnoreCase(gender)) {
                reciprocalLookupId = daughterLookupId;
            } else {
                reciprocalLookupId = childLookupId;
            }
            if (reciprocalLookupId == null) {
                reciprocalLookupId = childLookupId;
            }

            // Child -> Parent
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c        = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c           = parentLookupId,
                npe4__Status__c         = 'Current',
                npe4__Description__c    = 'Parent'
            ));

            // Parent -> Child (reciprocal type based on child's gender)
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c        = parentId,
                npe4__RelatedContact__c = childId,
                npe4__Type__c           = reciprocalLookupId,
                npe4__Status__c         = 'Current',
                npe4__Description__c    = 'Child'
            ));
        }

        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }
}
