public with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper result = new npsp.TDTM_Runnable.DmlWrapper();
        result.success = true;

        if (newlist == null || newlist.isEmpty()) {
            return result;
        }

        if (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert
            && triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate) {
            return result;
        }

        Set<Id> oppIds = new Set<Id>();
        for (SObject s : newlist) {
            if (s.Id != null) {
                oppIds.add(s.Id);
            }
        }

        if (oppIds.isEmpty()) {
            return result;
        }

        List<Opportunity> opps = [
            SELECT Id, StageName, Amount, CloseDate,
                   npsp__Primary_Contact__c, OwnerId
            FROM Opportunity
            WHERE Id IN :oppIds
        ];

        Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>();
        if (oldlist != null) {
            for (SObject s : oldlist) {
                if (s.Id != null) {
                    oldMap.put(s.Id, (Opportunity)s);
                }
            }
        }

        List<Task> tasksToInsert = new List<Task>();

        if (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert) {
            for (Opportunity opp : opps) {
                if (isQualified(opp)) {
                    tasksToInsert.add(buildTask(opp));
                }
            }
        } else if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
            for (Opportunity opp : opps) {
                Boolean nowQualified = isQualified(opp);
                Opportunity oldOpp = oldMap.get(opp.Id);
                Boolean wasQualified = (oldOpp != null) ? isQualified(oldOpp) : false;

                if (nowQualified && !wasQualified) {
                    tasksToInsert.add(buildTask(opp));
                }
            }
        }

        if (!tasksToInsert.isEmpty()) {
            try {
                insert tasksToInsert;
            } catch (Exception e) {
                result.success = false;
                result.message = e.getMessage();
            }
        }

        return result;
    }

    private Boolean isQualified(Opportunity opp) {
        return opp.StageName == 'Closed Won'
            && opp.Amount != null
            && opp.Amount >= 5000;
    }

    private Task buildTask(Opportunity opp) {
        Task t = new Task();
        t.Subject = 'Major gift thank-you call';
        t.Priority = 'High';
        t.Status = 'Not Started';
        t.WhatId = opp.Id;
        t.WhoId = opp.npsp__Primary_Contact__c;
        t.OwnerId = opp.OwnerId;
        if (opp.CloseDate != null) {
            t.ActivityDate = opp.CloseDate.addDays(3);
        }
        return t;
    }
}
