public with sharing class RecordAccessService {
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        List<Id> ids = new List<Id>(recordIds);
        ids.remove(null);

        if (ids.isEmpty()) {
            return editable;
        }

        Integer batchSize = 200;

        for (Integer i = 0; i < ids.size(); i += batchSize) {
            List<Id> batch = new List<Id>();
            Integer batchEnd = Math.min(i + batchSize, ids.size());
            for (Integer j = i; j < batchEnd; j++) {
                batch.add(ids[j]);
            }

            if (batch.isEmpty()) {
                continue;
            }

            for (UserRecordAccess ura : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :UserInfo.getUserId()
                AND RecordId IN :batch
            ]) {
                if (ura.HasEditAccess == true) {
                    editable.add(ura.RecordId);
                }
            }
        }

        return editable;
    }
}
