                    WhatId = acc.Id,
                    OwnerId = acc.OwnerId,
                    ActivityDate = dueDate,
                    Status = 'Not Started',
                    Priority = 'Normal'
                ));
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
