public inherited sharing class TA_Case_RollupOpenCount implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate, TriggerAction.AfterDelete, TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        doRollup(collectAccountIds(triggerNew, null));
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        doRollup(collectAccountIds(triggerNew, triggerOld));
    }

    public void afterDelete(List<SObject> triggerOld) {
        doRollup(collectAccountIds(null, triggerOld));
    }

    public void afterUndelete(List<SObject> triggerNew) {
        doRollup(collectAccountIds(triggerNew, null));
    }

    private Set<Id> collectAccountIds(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        if (triggerNew != null) {
            for (SObject s : triggerNew) {
                Case c = (Case) s;
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }
        }
        if (triggerOld != null) {
            for (SObject s : triggerOld) {
                Case c = (Case) s;
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }
        }
        return accountIds;
    }

    private void doRollup(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Map<Id, Integer> openCounts = new Map<Id, Integer>();
        for (AggregateResult ar : [
            SELECT AccountId, COUNT(Id) cnt
            FROM Case
            WHERE AccountId IN :accountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            openCounts.put((Id) ar.get('AccountId'), (Integer) ar.get('cnt'));
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account acc : [
            SELECT Id, FB_Open_Case_Count__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Integer newCount = openCounts.containsKey(acc.Id) ? openCounts.get(acc.Id) : 0;
            Integer currentCount = (acc.FB_Open_Case_Count__c == null) ? 0 : acc.FB_Open_Case_Count__c.intValue();
            if (currentCount != newCount) {
                acc.FB_Open_Case_Count__c = newCount;
                accountsToUpdate.add(acc);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
